
function byId(id){return document.getElementById(id);} 
function text(v){return v==null?'':String(v);} 
function htmlEscape(v){return text(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function normalizeSearch(v){return text(v).toLowerCase().replace(/[^a-z0-9]+/g,'');}
function slugify(value){return text(value).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');}
function safeParse(json){try{return JSON.parse(json);}catch(e){return [];}}
function storageGet(key){try{return window.localStorage?localStorage.getItem(key):null;}catch(e){return null;}}
function storageSet(key,val){try{if(window.localStorage){localStorage.setItem(key,val);}}catch(e){}}
var sharedApiBase='http://127.0.0.1:3210';
var sharedSaveTimer=null;
var sharedSaveInFlight=false;
var sharedSaveQueued=false;
function parseSharedRowsPayload(payload){ if(payload && payload.rows && payload.rows.length){ return dedupeExactRows(payload.rows); } return []; }
function loadSharedRowsSync(){ if(!window.XMLHttpRequest){ return []; } try{ var req=new XMLHttpRequest(); req.open('GET', sharedApiBase + '/api/rows?_=' + Date.now(), false); req.send(null); if(req.status>=200 && req.status<300){ return parseSharedRowsPayload(JSON.parse(req.responseText)); } }catch(e){} return []; }
function loadSharedRows(){ if(!window.fetch){ return; } fetch(sharedApiBase + '/api/rows?_=' + Date.now(), { cache:'no-store' }).then(function(res){ if(!res.ok){ throw new Error('shared-load'); } return res.json(); }).then(function(data){ var nextRows=parseSharedRowsPayload(data); if(nextRows.length){ rows=nextRows; storageSet(datasetKey, JSON.stringify(rows)); sync(); } }).catch(function(){}); }
function pushSharedRows(){ if(!window.fetch){ return; } sharedSaveInFlight=true; fetch(sharedApiBase + '/api/rows', { method:'POST', headers:{ 'Content-Type':'application/json' }, body:JSON.stringify({ rows:rows }) }).then(function(res){ if(!res.ok){ throw new Error('shared-save'); } return res.json(); }).catch(function(){}).finally(function(){ sharedSaveInFlight=false; if(sharedSaveQueued){ sharedSaveQueued=false; pushSharedRows(); } }); }
function scheduleSharedSave(){ if(!window.fetch){ return; } if(sharedSaveInFlight){ sharedSaveQueued=true; return; } if(sharedSaveTimer){ clearTimeout(sharedSaveTimer); } sharedSaveTimer=setTimeout(function(){ sharedSaveTimer=null; pushSharedRows(); }, 120); }
function normalizeDesignType(value){
  var raw=text(value).trim();
  var normalized=raw.toLowerCase().replace(/[^a-z]+/g,' ');
  if(!raw){return '';}
  if(normalized.indexOf('corner support')>-1){return 'Corner support';}
  if(normalized.indexOf('ball support')>-1){return 'Ball support';}
  if(normalized.indexOf('flat seating')>-1 || normalized.indexOf('seating plane')>-1 || normalized.indexOf('seating pane')>-1 || normalized.indexOf('qfp')>-1 || normalized.indexOf('shelf')>-1){return 'Flat seating';}
  if(normalized.indexOf('tapered')>-1 || normalized.indexOf('slope')>-1){return 'Tapered';}
  return raw;
}
function getPBinClass(value){
  var v=text(value).toLowerCase();
  if(!v){return '';}
  if(v.indexOf('light green')>-1){return 'pbin-tag pbin-light-green';}
  if(v.indexOf('green')>-1){return 'pbin-tag pbin-green';}
  if(v.indexOf('blue')>-1){return 'pbin-tag pbin-blue';}
  if(v.indexOf('yellow')>-1){return 'pbin-tag pbin-yellow';}
  if(v.indexOf('pink')>-1){return 'pbin-tag pbin-pink';}
  if(v.indexOf('gray')>-1 || v.indexOf('grey')>-1){return 'pbin-tag pbin-gray';}
  if(v.indexOf('brown')>-1){return 'pbin-tag pbin-brown';}
  if(v.indexOf('red')>-1){return 'pbin-tag pbin-red';}
  if(v.indexOf('white')>-1 || v==='x'){return 'pbin-tag pbin-white';}
  return 'pbin-tag';
}
function normalizePBinValue(value){
  var v=text(value).trim();
  if(!v || /^x$/i.test(v)){return '';}
  if(/brown\s*\/\s*yellow\s*p-?bin/i.test(v)){return 'Brown/Yellow';}
  if(/blue\s*\/\s*blue\s*p-?bin/i.test(v)){return 'Blue';}
  if(/\bblue\b/i.test(v)){return /blue\s*\/\s*green/i.test(v)?'Blue/Green':'Blue';}
  if(/light\s+green/i.test(v)){return 'Light Green';}
  if(/light\s+red/i.test(v)){return 'Light Red';}
  if(/green\s*\/\s*blue/i.test(v)){return 'Green/Blue';}
  if(/\bgreen\b/i.test(v)){return 'Green';}
  if(/brown\s*\/\s*yellow/i.test(v)){return 'Brown/Yellow';}
  if(/\byellow\b/i.test(v)){return 'Yellow';}
  if(/\bpink\b/i.test(v)){return 'Pink';}
  if(/\bgray\b|\bgrey\b/i.test(v)){return 'Gray';}
  if(/\bbrown\b/i.test(v)){return 'Brown';}
  if(/white\s*\/\s*blue/i.test(v)){return 'White/Blue';}
  if(/\bwhite\b/i.test(v)){return 'White';}
  if(/^1I010013$/i.test(v)){return 'Gray';}
  if(/^MPPO-GREEN$/i.test(v)){return 'MPPO-GREEN';}
  return v.replace(/\s*p-?bin\b/ig,'').replace(/\s{2,}/g,' ').trim();
}
function applyPBinFieldStyle(){
  var input=byId('entryExcelAA'), wrap=input&&input.parentNode, cls;
  if(!input || !wrap){return;}
  if(input.value!==normalizePBinValue(input.value)){ input.value=normalizePBinValue(input.value); }
  cls=getPBinClass(input.value);
  wrap.className='field'+(cls?(' '+cls):'');
}
function normalizeHL(value){
  var raw=text(value).replace(/\s+/g,' ').trim();
  if(!raw){return '';}
  if(/very\s*th(?:in|ink)/i.test(raw) || /non\s*-?\s*jedec/i.test(raw)){return 'Non-JEDEC';}
  if(/high/i.test(raw)){return 'High';}
  if(/2\.0/.test(raw)){return 'Low 2.0';}
  if(/low\s*profile/i.test(raw)){return 'Low 2.0';}
  if(/\blow\b/i.test(raw)){return 'Low 1.27';}
  return raw;
}
